function safeName(value: string) {
  return value.trim() || 'Untitled character';
}

export async function createBurningWheelPdf(character: BurningWheelCharacter) {
  const document = await PDFDocument.create();
  document.setTitle(`${safeName(character.identity.name)} — Burning Wheel`);
  document.setCreator('Arcane Record');
  const serif = await document.embedFont(StandardFonts.TimesRoman);
  const serifBold = await document.embedFont(StandardFonts.TimesRomanBold);
  const sans = await document.embedFont(StandardFonts.Helvetica);
  const totals = burnTotals(character);
  const derived = derivedAttributes(character);
  const pageSize: [number, number] = [792, 612];
  const ink = rgb(0.12, 0.1, 0.08);
  const accent = rgb(0.38, 0.08, 0.08);

  const addPage = (title: string) => {
    const page = document.addPage(pageSize);
    page.drawRectangle({
      x: 22,
      y: 22,
      width: 748,
      height: 568,
      borderColor: ink,
      borderWidth: 1,
    });
    page.drawText('ARCANE RECORD', {
      x: 40,
      y: 565,
      size: 9,
      font: sans,
      color: accent,
    });
    page.drawText(title, {
      x: 40,
      y: 536,
      size: 20,
      font: serifBold,
      color: ink,
    });
    return page;
  };
  const text = (
    page: PDFPage,
    value: string,
    x: number,
    y: number,
    size = 10,
    bold = false,
  ) =>
    page.drawText(value.replace(/[^\x20-\x7E]/g, '-'), {
      x,
      y,
      size,
      font: bold ? serifBold : serif,
      color: ink,
      maxWidth: 330,
    });

  const page = addPage('Burning Wheel Character Record');
  text(page, safeName(character.identity.name), 40, 505, 18, true);
  text(page, `${stockLabel(character.stock)} · Age ${totals.age}`, 40, 486, 11);
  text(page, `Player: ${character.identity.player || '-'}`, 410, 505, 10);
  text(page, `Concept: ${character.identity.concept || '-'}`, 410, 486, 10);
  text(page, 'Beliefs', 40, 452, 13, true);
  character.beliefs.forEach((belief, index) =>
    text(page, `${index + 1}. ${belief || '-'}`, 52, 430 - index * 22, 10),
  );
  text(page, 'Instincts', 410, 452, 13, true);
  character.instincts.forEach((instinct, index) =>
    text(page, `${index + 1}. ${instinct || '-'}`, 422, 430 - index * 22, 10),
  );
  text(page, 'Stats', 40, 348, 13, true);
  statDefinitions.forEach(({ id, label }, index) =>
    text(
      page,
      `${label}: ${character.burn.stats[id].shade}${derived.stats[id]}`,
      52 + (index % 3) * 112,
      324 - Math.floor(index / 3) * 22,
      11,
    ),
  );
  text(page, 'Attributes', 410, 348, 13, true);
  [
    ['Health', derived.health],
    ['Steel', derived.steel],
    ['Reflexes', derived.reflexes],
    ['Mortal Wound', derived.mortalWound],
    ['Hesitation', derived.hesitation],
    ['Stride', derived.stride],
  ].forEach(([label, value], index) =>
    text(
      page,
      `${label}: B${value}`,
      422 + (index % 2) * 150,
      324 - Math.floor(index / 2) * 22,
      10,
    ),
  );
  text(page, 'PTGS', 40, 250, 13, true);
  text(
    page,
    Object.entries(derived.ptgs)
      .map(([key, value]) => `${key.slice(0, 2).toUpperCase()} B${value}`)
      .join(' · '),
    52,
    228,
    10,
  );
  text(page, 'Artha', 40, 190, 13, true);
  text(
    page,
    `Fate ${character.play.artha.fate}   Persona ${character.play.artha.persona}   Deeds ${character.play.artha.deeds}`,
    52,
    168,
    11,
  );
  text(
    page,
    `Experience: ${character.play.experience.current} current / ${character.play.experience.total} total`,
    52,
    148,
    10,
  );
  text(page, 'Lifepaths', 410, 250, 13, true);
  character.burn.lifepaths.slice(0, 10).forEach((selected, index) => {
    const definition = burningWheelLifepathById.get(selected.definitionId);
    text(
      page,
      `${definition?.name ?? 'Unknown'} (${selected.time} yrs)`,
      422,
      228 - index * 16,
      9,
    );
  });

  const details = addPage('Skills, Traits, Connections & Gear');
  text(details, 'Skills', 40, 505, 13, true);
  character.burn.skills.slice(0, 22).forEach((skill, index) => {
    const name =
      (skill.definitionId &&
        burningWheelSkillById.get(skill.definitionId)?.name) ||
      skill.customName;
    text(
      details,
      `${name}: ${skillRating(character, skill)}`,
      52 + (index >= 11 ? 180 : 0),
      482 - (index % 11) * 18,
      9,
    );
  });
  text(details, 'Traits', 410, 505, 13, true);
  character.burn.traits.slice(0, 18).forEach((trait, index) => {
    const name =
      (trait.definitionId &&
        burningWheelTraitById.get(trait.definitionId)?.name) ||
      trait.customName;
    text(details, name, 422, 482 - index * 18, 9);
  });
  text(details, 'Connections', 40, 250, 13, true);
  [
    ...character.connections.relationships,
    ...character.connections.affiliations,
    ...character.connections.reputations,
  ]
    .slice(0, 10)
    .forEach((item, index) =>
      text(details, item.name, 52, 228 - index * 17, 9),
    );
  text(details, 'Gear & Property', 410, 250, 13, true);
  character.possessions
    .slice(0, 10)
    .forEach((item, index) =>
      text(
        details,
        `${item.name}${item.damaged ? ' [damaged]' : ''}`,
        422,
        228 - index * 17,
        9,
      ),
    );
  text(details, 'Notes', 40, 62, 13, true);
  text(details, character.play.notes.slice(0, 250) || '-', 100, 62, 9);
  return document.save();
}

import { z } from 'zod';
import {
  burningWheelGroupIds,
  defaultBurningWheelGroupOrder,
} from './definitions';
import { burningWheelStockIds } from './catalog';

const shadeSchema = z.enum(['B', 'G', 'W']);
const groupIdSchema = z.enum(burningWheelGroupIds);
const groupOrderSchema = z
  .array(groupIdSchema)
  .length(burningWheelGroupIds.length)
  .refine((order) => new Set(order).size === burningWheelGroupIds.length);
const testsSchema = z.object({
  routine: z.number().int().nonnegative(),
  difficult: z.number().int().nonnegative(),
  challenging: z.number().int().nonnegative(),
});
const statSchema = z.object({
  shade: shadeSchema,
  mentalPoints: z.number().int().nonnegative(),
  physicalPoints: z.number().int().nonnegative(),
  eitherPoints: z.number().int().nonnegative(),
  bonus: z.number().int(),
  tests: testsSchema,
});
const namedRecordSchema = z.object({
  id: z.string().uuid(),
  name: z.string(),
  notes: z.string(),
});

export const burningWheelCharacterSchema = z.object({
  stock: z.enum(burningWheelStockIds),
  mode: z.enum(['build', 'play']),
  identity: z.object({
    name: z.string(),
    player: z.string(),
    concept: z.string(),
    gender: z.string(),
  }),
  beliefs: z.array(z.string()).length(3),
  instincts: z.array(z.string()).length(3),
  burn: z.object({
    settings: z.object({
      enforceLifepathRequirements: z.boolean(),
      enforcePointLimits: z.boolean(),
      appropriateWeapons: z.record(z.string(), z.array(z.string())),
    }),
    lifepaths: z.array(
      z.object({
        id: z.string().uuid(),
        definitionId: z.string(),
        time: z.number().int().positive(),
        weaponChoice: z.string(),
        statChoice: z.enum(['', 'm', 'p']),
        brutalLifeDie: z.number().int().min(0).max(6),
        brutalLifeTrait: z.string(),
      }),
    ),
    stats: z.object({
      will: statSchema,
      perception: statSchema,
      power: statSchema,
      forte: statSchema,
      agility: statSchema,
      speed: statSchema,
    }),
    skills: z.array(
      z.object({
        id: z.string().uuid(),
        definitionId: z.string().nullable(),
        customName: z.string(),
        lifepathPoints: z.number().int().nonnegative(),
        generalPoints: z.number().int().nonnegative(),
        tests: testsSchema,
        notes: z.string(),
      }),
    ),
    traits: z.array(
      z.object({
        id: z.string().uuid(),
        definitionId: z.string().nullable(),
        customName: z.string(),
        notes: z.string(),
      }),
    ),
    attributeModifiers: z.record(z.string(), z.number().int()),
  }),
  connections: z.object({
    relationships: z.array(
      namedRecordSchema.extend({
        importance: z.enum(['minor', 'significant', 'powerful']),
        immediateFamily: z.boolean(),
        otherFamily: z.boolean(),
        romantic: z.boolean(),
        forbidden: z.boolean(),
        hateful: z.boolean(),
      }),
    ),
    affiliations: z.array(
      namedRecordSchema.extend({
        importance: z.enum(['small', 'large', 'national']),
      }),
    ),
    reputations: z.array(
      namedRecordSchema.extend({
        importance: z.enum(['local', 'regional', 'national']),
      }),
    ),
  }),
  possessions: z.array(
    namedRecordSchema.extend({
      kind: z.enum(['gear', 'property', 'weapon', 'armor']),
      definitionId: z.string().nullable(),
      cost: z.number().int().nonnegative(),
      damaged: z.boolean(),
    }),
  ),
  play: z.object({
    experience: z
      .object({
        total: z.number().int().nonnegative(),
        current: z.number().int().nonnegative(),
      })
      .default({ total: 0, current: 0 }),
    artha: z.object({
      fate: z.number().int().nonnegative(),
      persona: z.number().int().nonnegative(),
      deeds: z.number().int().nonnegative(),
    }),
    resourceTax: z.number().int().nonnegative(),
    wounds: z.array(
      namedRecordSchema.extend({
        severity: z.enum([
          'superficial',
          'light',
          'midi',
          'severe',
          'traumatic',
          'mortal',
        ]),
        obstacle: z.number().int().nonnegative(),
        treated: z.boolean(),
      }),
    ),
    advancement: z.array(
      z.object({
        id: z.string().uuid(),
        date: z.string(),
        target: z.string(),
        kind: z.enum(['test', 'advance', 'practice', 'artha']),
        difficulty: z.enum(['routine', 'difficult', 'challenging', '']),
        notes: z.string(),
      }),
    ),
    notes: z.string(),
  }),
  sheetLayout: z.object({
    buildGroupOrder: groupOrderSchema,
    playGroupOrder: groupOrderSchema,
  }),
});

export type BurningWheelCharacter = z.infer<typeof burningWheelCharacterSchema>;

export function migrateBurningWheelCharacter(
  data: unknown,
  fromVersion: number,
): BurningWheelCharacter {
  void fromVersion;
  const parsed = burningWheelCharacterSchema.safeParse(data);
  if (parsed.success) return parsed.data;
  throw new Error('The Burning Wheel character data could not be migrated.');
}

export const defaultGroupOrder = [...defaultBurningWheelGroupOrder];

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const sourceRoot = process.env.CHARRED_BLACK_SOURCE;
if (!sourceRoot) {
  throw new Error('Set CHARRED_BLACK_SOURCE to a Charred Black checkout.');
}

const projectRoot = process.cwd();
const readJson = async (...parts) =>
  JSON.parse(await readFile(path.join(sourceRoot, ...parts), 'utf8'));
const slug = (value) =>
  value
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

const stocks = ['man', 'dwarf', 'elf', 'orc', 'roden', 'wolf', 'troll'];
const stockLabels = {
  man: 'Man',
  dwarf: 'Dwarf',
  elf: 'Elf',
  orc: 'Orc',
  roden: 'Roden',
  wolf: 'Great Wolf',
  troll: 'Troll',
};

const goldSkills = await readJson('src', 'data', 'gold', 'skills.json');
const goldTraits = await readJson('src', 'data', 'gold', 'traits.json');
const wizardSkills = await readJson('src', 'data', 'wizard', 'skills.json');
const wizardTraits = await readJson('src', 'data', 'wizard', 'traits.json');
const darkElfSkills = await readJson('src', 'data', 'dark_elf', 'skills.json');
const darkElfTraits = await readJson('src', 'data', 'dark_elf', 'traits.json');
const trollSkills = await readJson('src', 'data', 'troll', 'skills.json');
const trollTraits = await readJson('src', 'data', 'troll', 'traits.json');

const skills = {
  ...goldSkills,
  ...wizardSkills,
  ...darkElfSkills,
  ...trollSkills,
};
const traits = {
  ...goldTraits,
  ...wizardTraits,
  ...darkElfTraits,
  ...trollTraits,
};

const lifepathsByStock = {};
const resourcesByStock = {};
const startingStatPointsByStock = {};
for (const stock of stocks) {
  const base =
    stock === 'troll' ? ['src', 'data', 'troll'] : ['src', 'data', 'gold'];
  lifepathsByStock[stock] = await readJson(
    ...base,
    ...(stock === 'troll'
      ? ['lifepaths.json']
      : ['lifepaths', `${stock}.json`]),
  );
  resourcesByStock[stock] = await readJson(
    ...base,
    ...(stock === 'troll'
      ? ['resources.json']
      : ['resources', `${stock}.json`]),
  );
  startingStatPointsByStock[stock] = await readJson(
    ...base,
    ...(stock === 'troll'
      ? ['starting_stat_pts.json']
      : ['starting_stat_pts', `${stock}.json`]),
  );
}

const wizardLifepaths = await readJson(
  'src',
  'data',
  'wizard',
  'lifepaths.json',
);
const man = lifepathsByStock.man;
man['College of Magic Setting'] = wizardLifepaths['College of Magic Setting'];
man['Death Cult Setting'] = wizardLifepaths['Death Cult Setting'];
Object.assign(
  lifepathsByStock.orc['Servant Of The Dark Blood Subsetting'],
  wizardLifepaths['Servant Of The Dark Blood Subsetting'],
);
for (const setting of [
  'Peasant Setting',
  'Villager Setting',
  'City Dweller Setting',
  'Noble Court Subsetting',
  'Outcast Subsetting',
]) {
  Object.assign(man[setting], wizardLifepaths[setting]);
}
for (const setting of [
  'Peasant Setting',
  'Villager Setting',
  'City Dweller Setting',
  'Seafaring Setting',
  'Servitude And Captive Setting',
]) {
  man[setting]['Gifted Child'] =
    wizardLifepaths['Special Gifted Lifepaths']['Gifted Child'];
}
for (const setting of [
  'Noble Court Subsetting',
  'Religious Subsetting',
  'Outcast Subsetting',
  'Professional Soldier Subsetting',
]) {
  man[setting]['Apt Pupil'] =
    wizardLifepaths['Special Gifted Lifepaths']['Apt Pupil'];
}

const darkElfLifepaths = await readJson(
  'src',
  'data',
  'dark_elf',
  'lifepaths.json',
);
lifepathsByStock.elf['Path Of Spite Subsetting'] =
  darkElfLifepaths['Path Of Spite Subsetting'];
resourcesByStock.elf.push(
  ...(await readJson('src', 'data', 'dark_elf', 'resources.json')),
);

const lifepaths = [];
for (const stock of stocks) {
  for (const [setting, definitions] of Object.entries(
    lifepathsByStock[stock],
  )) {
    for (const [name, definition] of Object.entries(definitions)) {
      lifepaths.push({
        id: `${stock}:${slug(setting)}:${slug(name)}`,
        stock,
        setting,
        name,
        displayName: definition.display_name ?? name,
        source:
          setting === 'Path Of Spite Subsetting'
            ? 'Burning Wheel Codex · Dark Elf'
            : ['College of Magic Setting', 'Death Cult Setting'].includes(
                  setting,
                ) ||
                Object.values(wizardLifepaths).some(
                  (entries) =>
                    entries && typeof entries === 'object' && name in entries,
                )
              ? 'Burning Wheel Codex · Wizard Burner'
              : ['roden', 'wolf'].includes(stock)
                ? 'Burning Wheel Revised · adapted by Charred Black'
                : stock === 'troll'
                  ? 'Burning Wheel Codex · Troll'
                  : 'Burning Wheel Gold',
        definition,
      });
    }
  }
}

const normalizeNamedCatalog = (entries, kind) => {
  const used = new Set();
  return Object.entries(entries)
    .map(([name, definition]) => {
      const baseId = `${kind}:${slug(name)}`;
      let id = baseId;
      if (used.has(id)) {
        const suffix = [...name].reduce(
          (hash, character) => (hash * 31 + character.codePointAt(0)) >>> 0,
          0,
        );
        id = `${baseId}-${suffix.toString(36)}`;
      }
      used.add(id);
      return { id, name, definition };
    })
    .sort((a, b) => a.name.localeCompare(b.name));
};

const catalog = {
  format: 'arcane-record-burning-wheel-catalog',
  formatVersion: 1,
  provenance: {
    project: 'Charred Black',
    repository: 'https://github.com/modality/charred-black',
    license: 'GPL-3.0',
    sourceCommit: '10f4e4afd1ef12135584b68a9dcd412442ebea3f',
    generatedAt: '2026-08-21',
  },
  stocks: stocks.map((id) => ({ id, label: stockLabels[id] })),
  lifepaths,
  skills: normalizeNamedCatalog(skills, 'skill'),
  traits: normalizeNamedCatalog(traits, 'trait'),
  resourcesByStock,
  startingStatPointsByStock,
};

const outputDirectory = path.join(
  projectRoot,
  'src',
  'games',
  'burning-wheel',
  'gpl-charred-black',
);
const docsDirectory = path.join(
  projectRoot,
  'docs',
  'references',
  'burning-wheel',
);
await mkdir(outputDirectory, { recursive: true });
await mkdir(docsDirectory, { recursive: true });
await writeFile(
  path.join(outputDirectory, 'catalog.json'),
  `${JSON.stringify(catalog, null, 2)}\n`,
);
await writeFile(
  path.join(outputDirectory, 'LICENSE'),
  await readFile(path.join(sourceRoot, 'LICENSE'), 'utf8'),
);
await writeFile(
  path.join(docsDirectory, 'charred-black-source.md'),
  `# Charred Black source provenance\n\nArcane Record's Burning Wheel catalog and burner engine are adapted from [modality/charred-black](https://github.com/modality/charred-black) at commit \`${catalog.provenance.sourceCommit}\`.\n\nThe adapted module is distributed under GPL-3.0. The original license is retained at \`src/games/burning-wheel/gpl-charred-black/LICENSE\`. Burning Wheel game terms and published material remain the property of their respective owners. This is an unofficial fan utility.\n`,
);

console.log(
  `Generated ${lifepaths.length} lifepaths, ${catalog.skills.length} skills, and ${catalog.traits.length} traits.`,
);
